import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;class ContractTest{@Test void allNoneEmptyAndInputKept(){Integer[]a={-3,2,-1};Integer[]copy=a.clone();assertEquals(3,TaskBinding.integers(a,1));assertEquals(0,TaskBinding.integers(a,2));assertEquals(2,TaskBinding.integers(a,3));assertArrayEquals(copy,a);assertEquals(0,TaskBinding.integers(new Integer[0],1));String[]s={"","😀","abcd","abcde"};String[]old=s.clone();assertEquals(2,TaskBinding.strings(s,0));assertEquals(4,TaskBinding.strings(s,1));assertEquals(0,TaskBinding.strings(s,2));assertArrayEquals(old,s);}}
